package com.tpverp.backend.pdawork;
import static org.assertj.core.api.Assertions.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;import org.junit.jupiter.api.Test;
class PdaStockLotTest{@Test void consumesTrackedLotAndRejectsConcurrentOrExcessQuantity(){var lot=new PdaStockLot(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"CAFE","L-01",LocalDate.of(2026,9,1),UUID.randomUUID(),"ALB-1",new BigDecimal("5"),Instant.now());lot.consume(new BigDecimal("2"),0,Instant.now());assertThat(lot.getQuantity()).isEqualByComparingTo("3");assertThatThrownBy(()->lot.consume(BigDecimal.ONE,1,Instant.now())).isInstanceOf(PdaWorkConflictException.class);assertThatThrownBy(()->lot.consume(new BigDecimal("4"),0,Instant.now())).hasMessageContaining("insuficiente");}}